const idx = document.createElement("span");
idx.className = "disc-index";
idx.textContent = "1";
```

But after that... it only appends `handle` and `text` to li! I never appended `idx` to li even once! Let me re-read the makeItem I wrote:

```js
function makeItem(item){
  const li = document.createElement("li");
  li.className = "disc-item";
  li.setAttribute("data-type", item.t);
  const idx = document.createTextNode?? 
```

From the file I wrote:

```js
function makeItem(item){
  const li = document.createElement("li");
  li.className = "disc-item";
  li.setAttribute("data-type", item.t);
  const idx = document.createElement("span");
