function send(method, params = {}) {
  const mid = ++id;
  return new Promise((resolve, reject) => {
    pending.set(mid, { resolve, reject });
    ws.send(JSON.stringify({ id: mid, method, params: { ...(sessionId.v ? { sessionId: sessionId.v } : {}), ...params } }));
